#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <limits.h>

#define MOD 1000000007LL

typedef struct {
    long long a, b, start;
} Line;

typedef struct {
    long long a, b;
} Effect;

static int cmp_line(const void *pa, const void *pb) {
    const Line *x = (const Line *)pa;
    const Line *y = (const Line *)pb;
    if (x->a < y->a) return -1;
    if (x->a > y->a) return 1;
    if (x->b > y->b) return -1;
    if (x->b < y->b) return 1;
    return 0;
}

static int cmp_meal(const void *pa, const void *pb) {
    const Effect *x = (const Effect *)pa;
    const Effect *y = (const Effect *)pb;

    if (x->a == 1 && y->a != 1) return -1;
    if (x->a != 1 && y->a == 1) return 1;
    if (x->a == 1) return 0;

    __int128 left = (__int128)x->b * (y->a - 1);
    __int128 right = (__int128)y->b * (x->a - 1);
    if (left > right) return -1;
    if (left < right) return 1;
    return 0;
}

static long long ceil_div(long long x, long long y) {
    if (x >= 0) return (x + y - 1) / y;
    return x / y;
}

static void affine_power(long long a, long long b, long long n,
                         long long *pa, long long *pb) {
    long long ra = 1, rb = 0;
    long long ba = a % MOD, bb = b % MOD;

    while (n > 0) {
        if (n & 1) {
            rb = (ba * rb + bb) % MOD;
            ra = (ba * ra) % MOD;
        }

        long long nbb = (ba * bb + bb) % MOD;
        long long nba = (ba * ba) % MOD;
        ba = nba;
        bb = nbb;
        n >>= 1;
    }

    *pa = ra;
    *pb = rb;
}

static long long apply_repetitions(long long a, long long b, long long n,
                                   long long xmod) {
    long long pa, pb;
    affine_power(a, b, n, &pa, &pb);
    return (pa * xmod + pb) % MOD;
}

int main(void) {
    int N, M;
    long long K;

    if (scanf("%d %d %lld", &N, &M, &K) != 3) return 0;

    Line *lines = (Line *)malloc((size_t)N * sizeof(Line));
    for (int i = 0; i < N; i++) scanf("%lld", &lines[i].a);
    for (int i = 0; i < N; i++) scanf("%lld", &lines[i].b);

    qsort(lines, N, sizeof(Line), cmp_line);

    int unique_count = 0;
    for (int i = 0; i < N; i++) {
        if (i == 0 || lines[i].a != lines[i - 1].a) {
            lines[unique_count++] = lines[i];
        }
    }

    Line *hull = (Line *)malloc((size_t)unique_count * sizeof(Line));
    int h = 0;

    for (int i = 0; i < unique_count; i++) {
        Line cur = lines[i];
        long long start = LLONG_MIN;

        while (h > 0) {
            long long numerator = hull[h - 1].b - cur.b;
            long long denominator = cur.a - hull[h - 1].a;
            start = ceil_div(numerator, denominator);

            if (start <= hull[h - 1].start) {
                h--;
            } else {
                break;
            }
        }

        if (h == 0) start = LLONG_MIN;
        cur.start = start;
        hull[h++] = cur;
    }
    free(lines);

    Effect *meals = (Effect *)malloc((size_t)M * sizeof(Effect));
    for (int i = 0; i < M; i++) scanf("%lld", &meals[i].a);
    for (int i = 0; i < M; i++) scanf("%lld", &meals[i].b);

    qsort(meals, M, sizeof(Effect), cmp_meal);

    long long meal_a = 1, meal_b = 0;
    for (int i = 0; i < M; i++) {
        long long a = meals[i].a % MOD;
        long long b = meals[i].b % MOD;
        meal_b = (a * meal_b + b) % MOD;
        meal_a = (a * meal_a) % MOD;
    }
    free(meals);

    int Q;
    scanf("%d", &Q);

    while (Q--) {
        long long x;
        scanf("%lld", &x);

        long long remaining = K;
        long long xmod = x % MOD;

        while (remaining > 0) {
            int lo = 0, hi = h;
            while (lo + 1 < hi) {
                int mid = lo + (hi - lo) / 2;
                if (hull[mid].start <= x) lo = mid;
                else hi = mid;
            }

            Line cur = hull[lo];

            if (lo == h - 1) {
                xmod = apply_repetitions(cur.a, cur.b, remaining, xmod);
                remaining = 0;
                break;
            }

            long long threshold = hull[lo + 1].start;
            long long count;
            long long next_x;

            if (cur.a == 1) {
                count = (threshold - x + cur.b - 1) / cur.b;
                if (remaining < count) {
                    xmod = apply_repetitions(cur.a, cur.b, remaining, xmod);
                    remaining = 0;
                    break;
                }
                next_x = x + count * cur.b;
            } else {
                next_x = x;
                count = 0;
                while (next_x < threshold) {
                    next_x = cur.a * next_x + cur.b;
                    count++;
                }
                if (remaining < count) {
                    xmod = apply_repetitions(cur.a, cur.b, remaining, xmod);
                    remaining = 0;
                    break;
                }
            }

            xmod = apply_repetitions(cur.a, cur.b, count, xmod);
            x = next_x;
            remaining -= count;
        }

        long long answer = (meal_a * xmod + meal_b) % MOD;
        printf("%lld\n", answer);
    }

    free(hull);
    return 0;
